{"packet_id":"D009-01","doc_id":"D009","jurisdiction":"Berkeley, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Berkeley rent control coverage (pre-1980 multifamily)","requirement":"Landlords may charge rent-controlled rents only for covered units: most multifamily properties built before 1980, single-family homes with tenancies that began before 1996, and rooming houses with five or more rooms. Units built after June 1980 and condominiums are not rent-controlled.","key_value":"Covered: built before 1980; Certificate of Occupancy after June 1980 not rent-controlled","coverage_conditions":"Most multifamily units built before 1980; single-family homes with pre-1996 tenancies; rooming houses with five or more rooms. Post-June-1980 construction, condominiums and post-1996 single-family tenancies are partially covered without rent control.","applicability":{"built_on_or_before":"1980","built_after":null,"date_basis":"certificate_of_occupancy","min_units":null,"max_units":null,"owner_dependent":true,"other":"multifamily properties; rooming houses with five or more rooms"},"exemptions":"Golden Duplex owner-occupied duplex; owner sharing kitchen or bath with tenant; ADU tenancies started after Nov 7, 2018 where either unit is owner-occupied; university dormitories; nonprofit cooperatives.","penalty":null,"effective_date":null,"citation":"Berkeley Rent Stabilization and Eviction for Just Cause Ordinance","quoted_span":"Most units in multifamily properties built before 1980** Fully Covered Yes Yes Yes Yes","interaction":null,"confidence":0.7,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D009-01","doc_id":"D009","jurisdiction":"Berkeley, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Berkeley just cause for eviction coverage","requirement":"A landlord may evict a tenant from a covered unit only for just cause under the ordinance. Fully and partially covered units, including post-June-1980 construction, condominiums and certain subsidized units, have just cause protection; exempt units do not.","key_value":null,"coverage_conditions":"Most rental units, including multifamily properties built before 1980, post-1980 new construction, condominiums, post-1996 single-family tenancies and specified subsidized units.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"All covered residential units; exempt categories excluded"},"exemptions":"Golden Duplex; owner sharing kitchen or bath with tenant; ADU tenancies started after Nov 7, 2018 where either unit is owner-occupied; university dormitories; nonprofit cooperatives.","penalty":null,"effective_date":null,"citation":"Berkeley Rent Stabilization and Eviction for Just Cause Ordinance","quoted_span":"Most condominiums** Partially Covered Yes No Yes Yes","interaction":null,"confidence":0.7,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D009-01","doc_id":"D009","jurisdiction":"Berkeley, CA","category":"security_deposits","lifecycle":"enacted","title":"Berkeley security deposit interest coverage","requirement":"Landlords must pay interest on security deposits for covered units under the ordinance. Fully and partially covered units receive security deposit interest; exempt units do not.","key_value":null,"coverage_conditions":"Covered units including most multifamily properties built before 1980, post-1980 new construction, condominiums, and specified subsidized units.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Covered residential units"},"exemptions":"Golden Duplex; owner sharing kitchen or bath with tenant; ADU tenancies after Nov 7, 2018 with owner-occupancy; university dormitories; nonprofit cooperatives.","penalty":null,"effective_date":null,"citation":"Berkeley Rent Stabilization and Eviction for Just Cause Ordinance","quoted_span":"Most units in multifamily properties built before 1980** Fully Covered Yes Yes Yes Yes","interaction":null,"confidence":0.6,"conflict_flag":false,"conflict_note":null}
